'use server'

import { refresh } from 'next/cache'
import { auth } from '@/lib/auth'
import { getNotificationsEnabled, setNotificationsEnabled } from '@/lib/db'

export async function toggleNotifications() {
  const session = await auth()
  if (!session?.user) {
    throw new Error('Unauthorized')
  }

  const userId = session.user.id
  const enabled = !(await getNotificationsEnabled(userId))
  await setNotificationsEnabled(userId, enabled)

  // Re-render the current route on the server and stream the new RSC Payload back
  // in the same roundtrip. No redirect, no client-side router call, and the URL
  // stays put. `refresh()` does not throw, so the action can still return a value.
  refresh()

  return enabled
}

