  // A plain <form action={...}> so the toggle still works before hydration.
  return (
    <form action={toggleNotifications}>
      <p>
        Notifications: <strong>{enabled ? 'On' : 'Off'}</strong>
      </p>
      <SubmitButton enabled={enabled} />
    </form>
  )
}

