/**
 * Stand-in for your auth provider. Server Functions are reachable via direct
 * POST requests, not just through your UI, so every one of them must verify the
 * session itself.
 *
 * Reading the request cookies is also what opts any route calling `auth()` into
 * dynamic rendering — without a request-time API the page would be prerendered
 * at build time and `refresh()` would have no dynamic work to rerun.
 */

export type Session = { user: { id: string } }

export async function auth(): Promise<Session | null> {
  const cookieStore = await cookies()
  // Replace with a real session lookup. This demo treats every visitor, signed
  // in or not, as the same user.
  return { user: { id: cookieStore.get('session')?.value ?? 'demo-user' } }
}

